from pathlib import Path
from reportlab.lib.colors import HexColor
from reportlab.lib.enums import TA_CENTER
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import inch
from reportlab.platypus import KeepTogether, SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle

BASE = Path(r"C:\Users\dolan\OneDrive - purdue.edu\2026-Fall\FIN-43900 - AI Finance Applications\projects\project-1\videos")
styles = getSampleStyleSheet()
title = ParagraphStyle("title", parent=styles["Title"], fontName="Helvetica-Bold", fontSize=18, leading=21, textColor=HexColor("#12355B"), alignment=TA_CENTER, spaceAfter=5)
subtitle = ParagraphStyle("subtitle", parent=styles["Normal"], fontName="Helvetica", fontSize=9.5, leading=12, textColor=HexColor("#4B5563"), alignment=TA_CENTER, spaceAfter=9)
h = ParagraphStyle("h", parent=styles["Heading2"], fontName="Helvetica-Bold", fontSize=12, leading=14, textColor=HexColor("#12355B"), spaceBefore=5, spaceAfter=3)
body = ParagraphStyle("body", parent=styles["BodyText"], fontName="Helvetica", fontSize=9.25, leading=12.2, spaceAfter=5)
cue = ParagraphStyle("cue", parent=body, fontName="Helvetica-Bold", textColor=HexColor("#0F766E"), backColor=HexColor("#ECFDF5"), borderColor=HexColor("#99F6E4"), borderWidth=0.5, borderPadding=5, spaceBefore=2, spaceAfter=4)
small = ParagraphStyle("small", parent=styles["Normal"], fontName="Helvetica", fontSize=7.8, leading=9.5, textColor=HexColor("#4B5563"))

def make_pdf(out, heading, target, rows, parts):
    story = [
        Paragraph(heading, title),
        Paragraph(f"Oladapo Olaniyan | FIN-43900 Project 1 | Recording target: {target}", subtitle),
        Paragraph("Use this on your phone while recording. Read one block at a time and follow the green SHOW or SWITCH cue. Show only the project files on your computer.", cue),
        Paragraph("Before you start", h),
    ]
    table_rows = [[Paragraph("Order", small), Paragraph("Show on your computer", small), Paragraph("What to say", small)]]
    table_rows += [[Paragraph(str(order), small), Paragraph(file, small), Paragraph(purpose, small)] for order, file, purpose in rows]
    table = Table(table_rows, colWidths=[0.45*inch, 2.3*inch, 3.9*inch])
    table.setStyle(TableStyle([
        ("BACKGROUND", (0,0), (-1,0), HexColor("#DCEAF7")),
        ("GRID", (0,0), (-1,-1), 0.35, HexColor("#CBD5E1")),
        ("VALIGN", (0,0), (-1,-1), "TOP"),
        ("LEFTPADDING", (0,0), (-1,-1), 6), ("RIGHTPADDING", (0,0), (-1,-1), 6),
        ("TOPPADDING", (0,0), (-1,-1), 5), ("BOTTOMPADDING", (0,0), (-1,-1), 5),
    ]))
    story += [table, Spacer(1, 6), Paragraph("Script", h)]
    for label, text in parts:
        story += [KeepTogether([Paragraph(label, cue), Paragraph(text, body)])]
    story += [Spacer(1, 3), Paragraph("After recording", h), Paragraph("Watch the recording once. Make the transcript from what you actually said, then correct only material finance terms, names, and numbers.", body)]
    doc = SimpleDocTemplate(str(out), pagesize=letter, leftMargin=0.55*inch, rightMargin=0.55*inch, topMargin=0.42*inch, bottomMargin=0.42*inch, title=heading)
    doc.build(story)

